import sys
from collections import Counter

def solve():
    n = int(sys.stdin.readline().strip())
    if n == 0:
        print(0)
        return

    arr = list(map(int, sys.stdin.readline().split()))

    freq = Counter(arr)
    odd_count = sum(1 for v in freq.values() if v % 2 == 1)

    if n % 2 == 0:
        if odd_count == 0:
            print(0)
        else:
            print(-1)
    else:
        print((odd_count - 1) // 2)

if __name__ == "__main__":
    solve()
